<script setup lang="ts">
import type { components } from '~/api/schema'; import { unwrap } from '~/api/client'; import { displayError } from '~/utils/errors'; import { formatDate, formatRupiah, statusLabel } from '~/utils/format';
type Quote = components['schemas']['QuoteRequest']; definePageMeta({ middleware: 'auth' }); const api = useMarketplaceApi(); const cartApi = useCart(); const quotes = ref<Quote[]>([]); const stores = ref<Record<string,string>>({}); const filter = ref('ALL'); const pending = ref(true); const error = ref<unknown>();
const visible = computed(() => filter.value === 'ALL' ? quotes.value : quotes.value.filter(q => q.status === filter.value || q.versions.some(v => v.status === filter.value)));
async function load() { pending.value = true; error.value = undefined; try { if (!cartApi.account.value) await cartApi.load(); const result = unwrap(await api.GET('/buyer-accounts/{buyerAccountId}/quote-requests', { params: { path: { buyerAccountId: cartApi.account.value!.id }, query: { limit: 100 } }, cache: 'no-store' })); quotes.value = result.items; const ids = [...new Set(result.items.map(q => q.store_id))]; const pairs = await Promise.all(ids.map(async id => { try { return [id,unwrap(await api.GET('/stores/{storeId}', { params: { path: { storeId: id } } })).name] as const; } catch { return [id,`Toko ${id.slice(0,8)}`] as const; } })); stores.value = Object.fromEntries(pairs); } catch (cause) { error.value = cause; } finally { pending.value = false; } }
onMounted(() => { void load(); }); useSeoMeta({ title: 'Penawaran — Niaga' });
</script>
<template><main id="main-content" class="page-shell"><BuyerNav/><div class="section-heading"><div><p class="eyebrow">Request for quotation</p><h1>Penawaran saya</h1></div><div class="form-actions"><select v-model="filter" class="select-control"><option value="ALL">Semua status</option><option value="SUBMITTED">Menunggu vendor</option><option value="OFFERED">Ditawarkan</option><option value="ACCEPTED">Diterima</option><option value="DECLINED">Ditolak</option><option value="EXPIRED">Kedaluwarsa</option><option value="CONSUMED">Digunakan</option></select><NuxtLink class="button" to="/cari">Cari produk untuk RFQ</NuxtLink></div></div><ApiState :pending="pending" :error="error ? displayError(error) : null" :empty="!pending && !visible.length" empty-title="Belum ada RFQ" empty-message="Buka detail produk lalu pilih Minta penawaran." @retry="load"><div class="order-list"><NuxtLink v-for="quote in visible" :key="quote.id" class="surface order-card" :to="`/akun/rfq/${quote.id}`"><header><div><strong>{{ stores[quote.store_id] }}</strong><small>{{ formatDate(quote.created_at) }} · {{ quote.items.length }} SKU</small></div><span class="badge badge--warning">{{ statusLabel(quote.status) }}</span></header><div v-for="version in quote.versions.slice(-1)" :key="version.id" class="summary-line"><span>Penawaran versi {{ version.version_no }}</span><strong>{{ formatRupiah(version.items.reduce((sum,item) => sum + item.unit_price_gross * item.quantity,0)) }}</strong></div></NuxtLink></div></ApiState></main></template>
